\label{lemma-explicit-metric}
For the diagonal matrices in \eqref{eq-thermal-diagonal-matrices} and \eqref{eq-weighted-diagonal-matrices}, and the symplectic matrix $ \mathbf{G} $ in \eqref{eq-williamson}, we have
\begin{equation}
    \label{eq-williamson-F-s}
    \mathbf{S}_s = \mathbf{G}^T
    \begin{bmatrix}D_{c_s} & \mathrm{i} D_{d_s}\\-\mathrm{i} D_{d_s} & D_{c_s} \end{bmatrix}
    \mathbf{G}.
\end{equation}
In particular,
\begin{equation}
    \label{eq-special-metrics}
    \mathbf{S}_0 = \mathbf{S} + \mathrm{i} \mathbf{J}, \qquad \mathbf{S}_1 = \mathbf{S} - \mathrm{i} \mathbf{J}, \qquad
    \mathbf{S}_{1/2} = \mathbf{G}^T \begin{bmatrix}D_{\csch} & 0\\0 & D_{\csch} \end{bmatrix}\mathbf{G}.
\end{equation}
Moreover, $ \mathbf{S}_{1 - s} = \overline{\mathbf{S}_s} $.

For positive definite matrices $ A $ and $ B $ of the same size and any invertible matrix $ R $, the weighted geometric mean satisfies
\begin{equation*}
    ( R^* A R ) \#_s ( R^* B R ) = R^* ( A \#_s B ) R.
\end{equation*}
Indeed, write $ A \#_s B = A ( A^{ - 1} B ) ^s $, where the power is defined by similarity with the positive matrix $ A^{ - 1/2} B A^{ - 1/2} $. The identity follows from
$ ( R^* A R ) ^{ - 1} ( R^* B R ) = R^{ - 1} ( A^{ - 1} B ) R $ and similarity invariance of the functional calculus.

Applying this identity to \eqref{eq-williamson}, it remains to compute
$ ( \mathbf{D}_{\coth} + \mathrm{i} \mathbf{J} ) \#_s ( \mathbf{D}_{\coth} - \mathrm{i} \mathbf{J} ) $. The two matrices commute. On the two-dimensional coordinate subspace corresponding to mode $ j $, the eigenvalues of $ \mathrm{i} \mathbf{J} $ are $ \pm 1 $, and
\begin{equation*}
    \coth ( \beta_j/2 ) \pm 1 = \frac{\mathrm{e}^{ \pm \beta_j/2}}{\sinh ( \beta_j/2 ) }.
\end{equation*}
The eigenvalues of their weighted geometric mean are thus
$ \mathrm{e}^{ \pm ( 1 - 2 s ) \beta_j/2}/\sinh ( \beta_j/2 ) = c_{s, j} \pm d_{s, j} $, where $ c_{s, j} $ and $ d_{s, j} $ are the coefficients in \eqref{eq-metric-coefficients}. This proves \eqref{eq-williamson-F-s}, the special cases in \eqref{eq-special-metrics}, and the identity $ \mathbf{S}_{1 - s} = \overline{\mathbf{S}_s} $. The same expressions also verify positivity directly.

\label{lemma-thermal-trace}
Let $ \rho_{\beta} $ be the one-mode thermal density in \eqref{eq-thermal-density}. For $ z, w \in \mathbb{C} $ and $ 0 \leq s \leq 1 $,
\begin{equation}
    \label{eq-thermal-trace}
    \Tr \bigl ( \rho_{\beta}^{1 - s} W ( - z ) \rho_{\beta}^s W ( w ) \bigr ) = \exp{
        - \frac{1}{2} \coth ( \beta/2 ) ( \abs{z}^2 + \abs{w}^2 )
        + \frac{\mathrm{e}^{ - s \beta} \overline{z} w + \mathrm{e}^{ - ( 1 - s ) \beta} z \overline{w}}{1 - \mathrm{e}^{ - \beta}}
    }.
\end{equation}

Apply \cite[Lemma~5.1, Eq.~(5.3)]{fagnola_li_2025spectral} with inverse temperature $ 2 \beta $, embedding parameter $ 1 - s $, and Weyl arguments $ - z $ and $ w $. The identity
\begin{equation*}
    \rho_{\beta} = \sqrt{\tanh ( \beta/2 )} \rho_{2 \beta}^{1/2}
\end{equation*}
cancels the prefactor $ \sqrt{\coth ( \beta/2 )} $ in that formula and gives \eqref{eq-thermal-trace}. The cited identity holds for every $ s \in [ 0, 1 ] $, including the endpoints.

\label{proposition-all-s-gram}
Let $ \rho $ be a faithful Gaussian state, not necessarily invariant. For every $ s \in [ 0, 1 ] $ and $ z, w \in \mathbb{C}^d $,
\begin{equation}
    \label{eq-all-s-gram}
    \left\langle \rho^{s/2} W ( z ) \rho^{ ( 1 - s ) /2},
    \rho^{s/2} W ( w ) \rho^{ ( 1 - s ) /2} \right\rangle_2 = \overline{\chi_\rho ( z )} \chi_\rho ( w )
    \exp{ \mathbf{z}^T \mathbf{S}_s \mathbf{w} }.
\end{equation}

Cyclicity of the trace gives
\begin{equation*}
    \left\langle \rho^{s/2} W ( z ) \rho^{ ( 1 - s ) /2},
    \rho^{s/2} W ( w ) \rho^{ ( 1 - s ) /2} \right\rangle_2  = \Tr \bigl ( \rho^{1 - s} W ( - z ) \rho^s W ( w ) \bigr ).
\end{equation*}
Schatten H\"{o}lder's inequality justifies the trace products and cyclic permutations, including $ s = 0 $ and $ s = 1 $. For one thermal mode with density $ \rho_{\beta} $, divide by $ \overline{\chi_{\rho_{\beta}} ( z )} \chi_{\rho_{\beta}} ( w ) $. The two diagonal terms in Lemma~\ref{lemma-thermal-trace} cancel, leaving the exponent
\begin{equation*}
    \frac{\mathrm{e}^{ - s \beta} \overline{z} w + \mathrm{e}^{ - ( 1 - s ) \beta} z \overline{w}}{1 - \mathrm{e}^{ - \beta}}
    = c_{s, 1} \Re \langle z, w \rangle + \mathrm{i} d_{s, 1} \Im \langle z, w \rangle,
\end{equation*}
where the coefficients in \eqref{eq-metric-coefficients} are evaluated at $ \beta_1 = \beta $. The $ s $-weighted covariance matrix is $ c_{s, 1} \1_2 + \mathrm{i} d_{s, 1} \mathbf{J} $. Taking tensor products gives the block matrix in \eqref{eq-williamson-F-s} for the thermal product state $ \rho_{\boldsymbol{\beta}} $ in \eqref{eq-thermal-product}.

For a general Gaussian state, use the thermal product representation \eqref{eq-thermal-product}. The Weyl relations and the Bogoliubov conjugation give
\begin{equation*}
    B ( \mathbf{G}^{ - 1} ) ^* W ( \omega ) ^* W ( z ) W ( \omega ) B ( \mathbf{G}^{ - 1} )
    = \mathrm{e}^{2 \mathrm{i} \Im \langle \omega, z \rangle} W ( Gz ).
\end{equation*}
Hence
\begin{equation*}
    \chi_\rho ( z ) = \mathrm{e}^{2 \mathrm{i} \Im \langle \omega, z \rangle} \chi_{\rho_{\boldsymbol{\beta}}} ( Gz ).
\end{equation*}
Conjugating the weighted trace by $ W ( \omega ) B ( \mathbf{G}^{ - 1} ) $, the Weyl factors $ W ( - z ) $ and $ W ( w ) $ contribute the phases $ \mathrm{e}^{ - 2 \mathrm{i} \Im \langle \omega, z \rangle} $ and $ \mathrm{e}^{2 \mathrm{i} \Im \langle \omega, w \rangle} $, respectively. Their product is $ \mathrm{e}^{2 \mathrm{i} \Im \langle \omega, w - z \rangle} $, which is also the phase in
\begin{equation*}
    \overline{\chi_\rho ( z )} \chi_\rho ( w )
    = \mathrm{e}^{2 \mathrm{i} \Im \langle \omega, w - z \rangle}
    \overline{\chi_{\rho_{\boldsymbol{\beta}}} ( Gz )} \chi_{\rho_{\boldsymbol{\beta}}} ( Gw ).
\end{equation*}
Thus unitary invariance of the trace and cancellation of this common factor give
\begin{equation*}
    \frac{\Tr \bigl ( \rho^{1 - s} W ( - z ) \rho^s W ( w ) \bigr )}{\overline{\chi_\rho ( z )} \chi_\rho ( w )}
    =
    \frac{\Tr \bigl ( \rho_{\boldsymbol{\beta}}^{1 - s} W ( - Gz ) \rho_{\boldsymbol{\beta}}^s W ( Gw ) \bigr )}{\overline{\chi_{\rho_{\boldsymbol{\beta}}} ( Gz )} \chi_{\rho_{\boldsymbol{\beta}}} ( Gw )}.
\end{equation*}
The thermal calculation applies to the right-hand side. Lemma~\ref{lemma-explicit-metric} identifies the resulting exponent as $ \mathbf{z}^T \mathbf{S}_s \mathbf{w} $, proving \eqref{eq-all-s-gram}.

\label{theorem-all-s-representation}
Suppose that $ \rho $ is a faithful Gaussian invariant state. For every $ s \in [ 0, 1 ] $ there is a unitary $ U_s : \Gamma ( \mathbb{C}^{2d} ) \to \mathcal{H} $ determined by
\begin{equation}
    \label{eq-all-s-unitary}
    U_s \, e ( \mathbf{S}_s^{1/2} \mathbf{z} ) = \chi_\rho ( z ) ^{ - 1} \rho^{s/2} W ( z ) \rho^{ ( 1 - s ) /2}, \qquad z \in \mathbb{C}^d.
\end{equation}
The transformed drift $ \mathbf{Z}_s $ in \eqref{eq-intro-second-quantization} satisfies
\begin{equation}
    \label{eq-definition-A-s}
    \mathrm{e}^{t \mathbf{Z}_s} = \mathbf{S}_s^{1/2} \mathrm{e}^{t \mathbf{Z}} \mathbf{S}_s^{ - 1/2}.
\end{equation}
It generates a contraction semigroup $ ( \mathrm{e}^{t \mathbf{Z}_s} ) _{t \geq 0} $ on $ \mathbb{C}^{2d} $, and
\begin{equation}
    \label{eq-all-s-second-quantization}
    U_s^*T_t^{ ( s ) } U_s = \Gamma ( \mathrm{e}^{t \mathbf{Z}_s} ), \qquad t \geq 0.
\end{equation}

Proposition~\ref{proposition-all-s-gram} shows that the prescription in \eqref{eq-all-s-unitary} preserves scalar products. We first verify totality. If $ f \in \Gamma ( \mathbb{C}^{2d} ) $ is orthogonal to every $ e ( \mathbf{S}_s^{1/2} x ) $, $ x \in \mathbb{R}^{2d} $, then the entire function
$ x \mapsto \langle f, e ( \mathbf{S}_s^{1/2} x ) \rangle $
vanishes on $ \mathbb{R}^{2d} $. Successive applications of the one-variable identity theorem show that it vanishes on $ \mathbb{C}^{2d} $. Since $ \mathbf{S}_s^{1/2} $ is invertible and exponential vectors are total, $ f = 0 $.

If $ Y \in \mathcal{H} $ is orthogonal to every embedded Weyl operator, then
\begin{equation*}
    \Tr \bigl ( \rho^{ ( 1 - s ) /2} Y^* \rho^{s/2} W ( z ) \bigr ) = 0,
    \qquad z \in \mathbb{C}^d.
\end{equation*}
The sandwiched operator is trace class by Schatten H\"{o}lder's inequality, including at $ s = 0 $ and $ s = 1 $. The $ \sigma $-weak density of the Weyl span therefore gives
$ \rho^{ ( 1 - s ) /2} Y^* \rho^{s/2} = 0 $.
Faithfulness of $ \rho $ implies $ Y = 0 $. Thus \eqref{eq-all-s-unitary} extends uniquely to a unitary $ U_s $.

Set $ V_t = U_s^* T_t^{ ( s ) } U_s $. It is contractive because $ T_t^{ ( s ) } $ is a contraction and $ U_s $ is unitary. Equation~\eqref{eq-all-s-unitary} gives
\begin{equation*}
    U_s^* \bigl ( \rho^{s/2} W ( z ) \rho^{ ( 1 - s ) /2} \bigr )
    = \chi_\rho ( z ) e ( \mathbf{S}_s^{1/2} \mathbf{z} ), \qquad z \in \mathbb{C}^d.
\end{equation*}
Invariance gives $ \chi_\rho ( z ) = \phi_t ( z ) \chi_\rho ( \mathrm{e}^{tZ} z ) $. Thus \eqref{eq-construction-induced-semigroup} and \eqref{eq-gaussian-action} yield
\begin{equation*}
    V_t \, e ( \mathbf{S}_s^{1/2} \mathbf{z} )
    = \frac{\phi_t ( z )}{\chi_\rho ( z )}
    U_s^* \bigl ( \rho^{s/2} W ( \mathrm{e}^{tZ} z ) \rho^{ ( 1 - s ) /2} \bigr ) = \frac{\phi_t ( z ) \chi_\rho ( \mathrm{e}^{tZ} z )}{\chi_\rho ( z )}
    e ( \mathbf{S}_s^{1/2} \mathrm{e}^{t \mathbf{Z}} \mathbf{z} ) = e ( \mathbf{S}_s^{1/2} \mathrm{e}^{t \mathbf{Z}} \mathbf{z} ).
\end{equation*}
Every $ x \in \mathbb{R}^{2d} $ is $ \mathbf{z} = \iota ( z ) $ for some $ z \in \mathbb{C}^d $, so
$ V_t \, e ( \mathbf{S}_s^{1/2} x ) = e ( \mathbf{S}_s^{1/2} \mathrm{e}^{t \mathbf{Z}} x ) $.
Both sides are entire vector-valued functions of $ x $. Applying the same uniqueness argument after taking scalar products extends the identity to every $ x \in \mathbb{C}^{2d} $. Since $ \mathbf{S}_s^{1/2} $ is invertible, this gives
\begin{equation*}
    V_t \, e ( \xi ) = e ( \mathrm{e}^{t \mathbf{Z}_s} \xi ), \qquad \xi \in \mathbb{C}^{2d}.
\end{equation*}
Contractivity of $ V_t $ and the identity $ \norm{e ( \xi )} = \exp{ \abs{\xi}^2/2 } $ imply $ \abs{\mathrm{e}^{t \mathbf{Z}_s} \xi} \leq \abs{\xi} $ for every $ \xi \in \mathbb{C}^{2d} $. Hence $ \Gamma ( \mathrm{e}^{t \mathbf{Z}_s} ) $ is a contraction by \cite[Lemma~3.1 and Theorem~3.3(a)]{ArakiSinhaSunder1995}. Its agreement with $ V_t $ on exponential vectors proves \eqref{eq-all-s-second-quantization}.

\label{corollary-generator-domain}
Under the assumptions of Theorem~\ref{theorem-all-s-representation},
\begin{equation}
    \label{eq-second-quantized-generator}
    U_s^*L^{ ( s ) } U_s = \lambda ( \mathbf{Z}_s ) = \bigoplus_{n = 0}^\infty \mathbf{Z}_{s, n}, \qquad
    \mathbf{Z}_{s, n} := \left.\sum_{j = 1}^n\1^{ \otimes ( j - 1 ) } \otimes \mathbf{Z}_s \otimes \1^{ \otimes ( n - j ) }
    \right|_{( \mathbb{C}^{2d} ) ^{ \odot n}},
\end{equation}
where $ \mathbf{Z}_{s, 0} = 0 $. The domain of $ U_s^* L^{ ( s ) } U_s $ is
\begin{equation}
    \label{eq-second-quantized-domain}
    \left\{ f = \bigoplus_{n = 0}^\infty f_n \in \Gamma ( \mathbb{C}^{2d} ) : \sum_{n = 0}^\infty \norm{\mathbf{Z}_{s, n} f_n}^2 < \infty \right\}.
\end{equation}
Here $ f_n $ is the orthogonal projection of $ f $ onto the $ n $-particle subspace $ ( \mathbb{C}^{2d} ) ^{ \odot n} $, as in Subsection~\ref{subsection-gaussian}. Vectors with only finitely many nonzero particle components form a core for $ U_s^* L^{ ( s ) } U_s $, and their images under $ U_s $ form a core for $ L^{ ( s ) } $.

By Theorem~\ref{theorem-all-s-representation}, for $ f = \bigoplus_{n = 0}^\infty f_n \in \Gamma ( \mathbb{C}^{2d} ) $ and $ t > 0 $,
\begin{equation*}
    U_s^* \frac{T_t^{ ( s ) } U_s f - U_s f}{t}
    = \bigoplus_{n = 0}^\infty \frac{\mathrm{e}^{t \mathbf{Z}_{s, n}} - \1}{t} f_n.
\end{equation*}
Since $ U_s $ is unitary, $ U_s f $ belongs to $ \operatorname{Dom} L^{ ( s ) } $ precisely when this difference quotient converges in Fock space as $ t \downarrow 0 $. Its limit is then $ U_s^* L^{ ( s ) } U_s f $.

Suppose first that $ U_s f \in \operatorname{Dom} L^{ ( s ) } $. Projection onto the $ n $-particle subspace commutes with taking this limit. On that finite-dimensional subspace, the derivative of $ \mathrm{e}^{t \mathbf{Z}_{s, n}} f_n $ at zero is $ \mathbf{Z}_{s, n} f_n $. Thus the particle components of $ U_s^* L^{ ( s ) } U_s f $ are $ \mathbf{Z}_{s, n} f_n $, and
\begin{equation*}
    \sum_{n = 0}^\infty \norm{\mathbf{Z}_{s, n} f_n}^2
    = \norm{L^{ ( s ) } U_s f}_2^2 < \infty.
\end{equation*}
This proves the necessity of \eqref{eq-second-quantized-domain}.

Conversely, suppose that $ f $ belongs to the set in \eqref{eq-second-quantized-domain}. For each $ n $,
\begin{equation*}
    \frac{\mathrm{e}^{t \mathbf{Z}_{s, n}} - \1}{t} f_n
    = \frac{1}{t} \int_0^t \mathrm{e}^{r \mathbf{Z}_{s, n}} \mathbf{Z}_{s, n} f_n \, \mathrm{d} r.
\end{equation*}
Since $ \mathrm{e}^{r \mathbf{Z}_{s, n}} = ( \mathrm{e}^{r \mathbf{Z}_s} ) ^{ \odot n} $ is contractive, the norm of this quotient is at most $ \norm{\mathbf{Z}_{s, n} f_n} $. Its difference from $ \mathbf{Z}_{s, n} f_n $ therefore has norm at most $ 2 \norm{\mathbf{Z}_{s, n} f_n} $ and tends to zero for each $ n $. The square-summability assumption permits dominated convergence in the sum of these squared norms. Hence the full difference quotient converges to $ \bigoplus_{n = 0}^\infty \mathbf{Z}_{s, n} f_n $, proving that $ U_s f \in \operatorname{Dom} L^{ ( s ) } $ and
\begin{equation*}
    L^{ ( s ) } U_s f = U_s \left( \bigoplus_{n = 0}^\infty \mathbf{Z}_{s, n} f_n \right).
\end{equation*}

Finally, let $ f^{ ( r ) } $ be the truncation of $ f $ to its first $ r + 1 $ particle components. Then
\begin{equation*}
    \norm{U_s f - U_s f^{ ( r ) }}_2^2
    + \norm{L^{ ( s ) } U_s f - L^{ ( s ) } U_s f^{ ( r ) }}_2^2
    = \sum_{n > r} \left( \norm{f_n}^2 + \norm{\mathbf{Z}_{s, n} f_n}^2 \right) \longrightarrow 0.
\end{equation*}
Thus these truncations converge in the graph norm. This proves the core assertions and identifies the conjugated generator with the closure of the finite-particle action defining $ \lambda ( \mathbf{Z}_s ) $.

\label{remark-comparison-metrics}
At the endpoints and at $ s = 1/2 $, the weighted covariance matrices in \eqref{eq-special-metrics} recover the GNS, anti-GNS, and KMS representations in \eqref{eq-intro-second-quantization}. In general, $ \mathbf{S}_s $ and $ \mathbf{Z}_s $ may be complex; the KMS weighted covariance matrix $ \mathbf{S}_{1/2} $ is real. The matrices $ \mathbf{Z}_s $ are similar, but lifting a one-particle similarity to Fock space requires control of every tensor power. For an invertible one-particle matrix $ R $,
\begin{equation*}
    \norm{R^{ \odot n}} = \norm{R}^n, \qquad
    \norm{( R^{ - 1} ) ^{ \odot n}} = \norm{R^{ - 1}}^n;
\end{equation*}
see \cite[Lemma~3.1]{ArakiSinhaSunder1995}. If either norm exceeds one, the corresponding direct sum is unbounded. Both lifts are bounded only when $ R $ is unitary. Thus finite-dimensional similarity alone does not establish bounded similarity of the Fock-space generators; their closed realizations are determined by the unitary construction and the domain formula above.

By \cite[Theorems~11 and~13]{girotti2025gaussian}, a fixed Gaussian unitary conjugation identifies $ \Gamma ( \mathbb{C}^d ) $ with $ \Gamma ( \mathbb{C}^{d_0} ) \otimes \Gamma ( \mathbb{C}^{d_{-} } ) $, where $ d_0 + d_{-} = d $, and gives
\begin{equation}
    \label{eq-invariant-decomposition}
    \mathcal{T}_t ( X_0 \otimes X_{-} )
    = \bigl ( \mathrm{e}^{\mathrm{i} tH_0} X_0 \mathrm{e}^{ - \mathrm{i} tH_0} \bigr ) \otimes \mathcal{T}_{-, t} ( X_{-} ).
\end{equation}
Here $ H_0 = \sum_{j = 1}^{d_0} \omega_j N_j $, with $ \omega_j \in \mathbb{R} $, and $ ( \mathcal{T}_{-, t} ) _{t \geq 0} $ is the Gaussian QMS on $ \mathcal{B} ( \Gamma ( \mathbb{C}^{d_{-} } ) ) $ whose drift is stable. It has a unique normal invariant state $ \rho_{-} $, which is Gaussian. Every invariant density is $ \rho_0 \otimes \rho_{-} $, where $ \rho_0 $ commutes with $ \mathrm{e}^{\mathrm{i} tH_0} $ for every $ t \in \mathbb{R} $. Faithfulness of the invariant density implies faithfulness of both factors. A factor with no modes is understood as $ \mathbb{C} $.

This commutation shows that the induced action on the first Hilbert--Schmidt factor is the same unitary conjugation. Hence, for elementary Hilbert--Schmidt tensors,
\begin{equation}
    \label{eq-induced-factorization}
    T_t^{ ( s ) } ( Y_0 \otimes Y_{-} )
    = \bigl ( \mathrm{e}^{\mathrm{i} tH_0} Y_0 \mathrm{e}^{ - \mathrm{i} tH_0} \bigr ) \otimes T_{-, t}^{ ( s ) } ( Y_{-} ),
\end{equation}
where $ T_{-, t}^{ ( s ) } $ is induced by $ \mathcal{T}_{-, t} $ and $ \rho_{-} $. Density extends this identity to the full Hilbert--Schmidt space.

The right-hand side of \eqref{eq-induced-factorization} is independent of $ \rho_0 $. A faithful product thermal density commutes with $ H_0 $, so it can be chosen as $ \rho_0 $. The resulting product $ \rho_0 \otimes \rho_{-} $ is Gaussian and faithful. Undoing the Gaussian unitary conjugation gives the reference density $ \sigma $, to which Theorem~\ref{theorem-all-s-representation} applies.

By Proposition~\ref{proposition-state-independence}, we may use a faithful Gaussian invariant reference state and apply Theorem~\ref{theorem-all-s-representation}. Fix $ s \in [ 0, 1 ] $. Applying the contraction $ \mathrm{e}^{t \mathbf{Z}_s} $ to an eigenvector shows that every eigenvalue $ \lambda $ of $ \mathbf{Z}_s $ satisfies $ \Re \lambda \leq 0 $. Since $ \mathbf{Z}_s $ is similar to $ \mathbf{Z} $, failure of stability gives an eigenvalue $ \mathrm{i} \omega $ with $ \omega \in \mathbb{R} $.

By Corollary~\ref{corollary-generator-domain}, every finite-particle vector $ f $ belongs to the domain of $ \lambda ( \mathbf{Z}_s ) $, and
\begin{equation*}
    L^{ ( s ) } U_s f = U_s \lambda ( \mathbf{Z}_s ) f.
\end{equation*}
Thus it suffices to construct infinitely many orthogonal finite-particle vectors annihilated by $ \lambda ( \mathbf{Z}_s ) $.

If $ \omega = 0 $, choose a nonzero vector $ u $ with $ \mathbf{Z}_s u = 0 $. For $ n \geq 1 $, put $ v_n = u^{ \otimes n} \in ( \mathbb{C}^{2d} ) ^{ \odot n} $. The tensor-factor formula in \eqref{eq-second-quantized-generator} gives
\begin{equation*}
    \lambda ( \mathbf{Z}_s ) v_n
    = \sum_{j = 1}^n u^{ \otimes ( j - 1 ) } \otimes ( \mathbf{Z}_s u ) \otimes u^{ \otimes ( n - j ) }
    = 0.
\end{equation*}
If $ \omega \neq 0 $, reality of $ \mathbf{Z} $ and similarity of $ \mathbf{Z}_s $ to $ \mathbf{Z} $ imply that $ - \mathrm{i} \omega $ is also an eigenvalue. Choose nonzero eigenvectors $ u_{+} $ and $ u_{-} $ such that $ \mathbf{Z}_s u_{+} = \mathrm{i} \omega u_{+} $ and $ \mathbf{Z}_s u_{-} = - \mathrm{i} \omega u_{-} $. Set
\begin{equation*}
    v_n = u_{+} ^{ \odot n} \odot u_{-} ^{ \odot n} \in ( \mathbb{C}^{2d} ) ^{ \odot 2n}, \qquad n \geq 1.
\end{equation*}
Differential second quantization applies $ \mathbf{Z}_s $ to each of the $ 2n $ factors and sums the results. The $ n $ factors $ u_{+} $ contribute $ n \mathrm{i} \omega v_n $, while the $ n $ factors $ u_{-} $ contribute $ - n \mathrm{i} \omega v_n $. Hence
\begin{equation*}
    \lambda ( \mathbf{Z}_s ) v_n = n \mathrm{i} \omega v_n - n \mathrm{i} \omega v_n = 0.
\end{equation*}
These tensors are nonzero: under the identification with homogeneous polynomials, they are products of nonzero linear polynomials. The vacuum is also annihilated by $ \lambda ( \mathbf{Z}_s ) $. In both cases, the vectors $ v_n $ lie in distinct particle subspaces, so normalization gives infinitely many orthonormal vectors. Their Hilbert--Schmidt images satisfy
\begin{equation*}
    U_s v_n \in \operatorname{Dom} L^{ ( s ) }, \qquad
    L^{ ( s ) } U_s v_n = U_s \lambda ( \mathbf{Z}_s ) v_n = 0.
\end{equation*}
After normalization, their images under $ U_s $ form an orthonormal sequence in $ \ker L^{ ( s ) } $.

Suppose first that \ref{condition-stable} holds. The invariant-state structure in \cite[Theorems~11 and~13]{girotti2025gaussian}, recalled in Proposition~\ref{proposition-state-independence}, gives a unique normal invariant state and shows that $ \rho $ is Gaussian. Fix $ s \in [ 0, 1 ] $. By Theorem~\ref{theorem-all-s-representation}, the induced semigroup is unitarily equivalent to $ \Gamma ( \mathrm{e}^{t \mathbf{Z}_s} ) $. The matrices $ \mathrm{e}^{t \mathbf{Z}_s} $ are contractions and converge to zero because $ \mathbf{Z}_s $ is similar to the stable matrix $ \mathbf{Z} $.

In fact, $ \norm{\mathrm{e}^{t \mathbf{Z}_s}} < 1 $ for every $ t > 0 $. Otherwise, finite dimensionality gives a unit vector $ v $ and $ t_0 > 0 $ such that $ \abs{\mathrm{e}^{t_0 \mathbf{Z}_s} v} = 1 $. Contractivity and the semigroup property imply
\begin{equation*}
    1 = \abs{\mathrm{e}^{t_0 \mathbf{Z}_s} v} \leq \abs{\mathrm{e}^{t \mathbf{Z}_s} v} \leq 1,
    \qquad 0 \leq t \leq t_0.
\end{equation*}
The real-analytic function $ t \mapsto \abs{\mathrm{e}^{t \mathbf{Z}_s} v}^2 $ is therefore constant on an interval, and hence on $ \mathbb{R} $, contradicting its convergence to zero.

For $ t > 0 $, let $ Q_{\leq r} $ be the projection onto $ \bigoplus_{n = 0}^r ( \mathbb{C}^{2d} ) ^{ \odot n} $. The symmetric tensor norm identity in \cite[Lemma~3.1]{ArakiSinhaSunder1995} gives
\begin{equation}
    \label{eq-chaos-tail}
    \norm{\Gamma ( \mathrm{e}^{t \mathbf{Z}_s} ) - \Gamma ( \mathrm{e}^{t \mathbf{Z}_s} ) Q_{\leq r}}
    = \norm{\mathrm{e}^{t \mathbf{Z}_s}}^{r + 1} \longrightarrow 0, \qquad r \to \infty.
\end{equation}
Since $ Q_{\leq r} $ has finite rank, this proves \ref{condition-immediate}. Moreover, $ \mathrm{e}^{t \mathbf{Z}_s} $ is trace class on $ \mathbb{C}^{2d} $, so \cite[Theorem~3.10(a)]{ArakiSinhaSunder1995} proves \ref{condition-trace-class}.

Trace-class membership implies compactness, so \ref{condition-trace-class} implies \ref{condition-immediate}, which implies \ref{condition-one-time}. Immediate compactness also gives compact resolvent by \cite[Theorem~II.4.29]{EngelNagel2000}, proving \ref{condition-resolvent}. If $ T_t^{ ( s ) } $ is compact at one positive time, its restriction to $ \ker L^{ ( s ) } $ is the identity, so this kernel is finite dimensional. If $ L^{ ( s ) } $ has compact resolvent, then, for $ \lambda > 0 $, the restriction of $ ( \lambda - L^{ ( s ) } ) ^{ - 1} $ to the kernel is $ \lambda^{ - 1}\1 $, which gives the same conclusion. Thus both \ref{condition-one-time} and \ref{condition-resolvent} imply \ref{condition-kernel}. The converse implication from \ref{condition-kernel} to \ref{condition-stable} follows from Lemma~\ref{lemma-infinite-fixed-space}.

To complete the equivalences, suppose that \ref{condition-stable} fails. Then the oscillator factor in \eqref{eq-invariant-decomposition} has $ d_0 \geq 1 $. The number vectors $ e ( n, 0, \ldots, 0 ) $ are eigenvectors of $ H_0 $. Thus the densities
\begin{equation*}
    \ketbra{e ( n, 0, \ldots, 0 )}{e ( n, 0, \ldots, 0 )} \otimes \rho_{-}, \qquad n \in \mathbb{N},
\end{equation*}
define distinct normal invariant states in this representation. This proves that \ref{condition-unique} implies \ref{condition-stable}.

Finally, assume that the drift is stable. The vacuum is the unit vector $ e ( 0 ) = 1 \oplus 0 \oplus \cdots $ in $ \Gamma ( \mathbb{C}^{2d} ) $. Since $ \norm{\mathrm{e}^{t \mathbf{Z}_s}} \leq 1 $, we have
\begin{equation*}
    \norm{\Gamma ( \mathrm{e}^{t \mathbf{Z}_s} ) - \ketbra{e ( 0 )}{e ( 0 )}}
    = \sup_{n \geq 1} \norm{\mathrm{e}^{t \mathbf{Z}_s} }^n = \norm{\mathrm{e}^{t \mathbf{Z}_s} } \longrightarrow 0.
\end{equation*}
Since $ U_s e ( 0 ) = \rho^{1/2} $, the limiting projection on $ \mathcal{H} $ is $ \ketbra{\rho^{1/2}}{\rho^{1/2}} $. Its range is $ \mathbb{C} \rho^{1/2} $, so $ \ker L^{ ( s ) } = \mathbb{C} \rho^{1/2} $. In the nonstable case, the kernel is infinite dimensional by Lemma~\ref{lemma-infinite-fixed-space}.

\label{example-nonunique}
On one mode, let $ H = \omega N $, where $ \omega \in \mathbb{R} $, and set
$ \mathcal{T}_t ( X ) = \mathrm{e}^{\mathrm{i} tH} X \mathrm{e}^{ - \mathrm{i} tH} $. This Gaussian QMS has drift $ Zz = \mathrm{i} \omega z $ and zero diffusion. Every thermal density $ \rho_{\beta} $ in \eqref{eq-thermal-density} is a faithful normal Gaussian invariant state. More generally, every normal state diagonal in the number basis is invariant.

Let $ e_n $, $ n \in \mathbb{N} $, be the normalized number vectors. Since $ H e_n = \omega n e_n $, we have $ \mathcal{T}_t ( \ketbra{e_n}{e_n} ) = \ketbra{e_n}{e_n} $. For the embedding associated with $ \rho_{\beta} $,
\begin{equation*}
    \rho_{\beta}^{s/2} \ketbra{e_n}{e_n} \rho_{\beta}^{ ( 1 - s ) /2} = \sqrt{1 - \mathrm{e}^{ - \beta}} \mathrm{e}^{ - \beta n/2} \ketbra{e_n}{e_n}.
\end{equation*}
The coefficient is positive, so \eqref{eq-construction-induced-semigroup} gives $ T_t^{ ( s ) } \ketbra{e_n}{e_n} = \ketbra{e_n}{e_n} $ for every $ t \geq 0 $ and $ s \in [ 0, 1 ] $. Moreover, $ \langle \ketbra{e_m}{e_m}, \ketbra{e_n}{e_n} \rangle_2 = \delta_{mn} $, so $ ( \ketbra{e_n}{e_n} ) _{n \in \mathbb{N}} $ is an orthonormal sequence in $ \mathcal{H} $. For $ m \neq n $,
\begin{equation*}
    \norm{\ketbra{e_n}{e_n} - \ketbra{e_m}{e_m}}_2 = \sqrt{2}.
\end{equation*}
Thus the image of this bounded sequence has no norm-convergent subsequence. A compact operator maps every bounded sequence to one with a convergent subsequence, so $ T_t^{ ( s ) } $ is noncompact for every $ t > 0 $.

These fixed vectors belong to the generator domain and satisfy $ L^{ ( s ) } \ketbra{e_n}{e_n} = 0 $. Hence, for $ \eta > 0 $,
\begin{equation*}
    ( \eta \1 - L^{ ( s ) } ) ^{ - 1} \ketbra{e_n}{e_n} = \eta^{ - 1} \ketbra{e_n}{e_n}.
\end{equation*}
The resolvent is noncompact for the same reason. Tensoring this oscillator with a stable dissipative Gaussian QMS with faithful invariant density $ \rho_{-} $ preserves the obstruction: the vectors $ \ketbra{e_n}{e_n} \otimes \rho_{-}^{1/2} $ form an orthonormal sequence fixed by the induced semigroup in \eqref{eq-induced-factorization}. Both constructions are elementary instances of Proposition~\ref{proposition-state-independence}.

\label{corollary-traces}
Assume the equivalent conditions of Theorem~\ref{theorem-main}. For $ t > 0 $ and $ s \in [ 0, 1 ] $, we have
\begin{align}
    \norm{T_t^{ ( s ) }}_{\mathcal{S}_1}
    & = \det ( \1_{2d} - \abs{\mathrm{e}^{t \mathbf{Z}_s}} ) ^{ - 1}, \label{eq-all-s-schatten}\\*
    \norm{T_t^{ ( s ) }}_{\mathcal{S}_2}^{2}
    & = \det \bigl ( \1_{2d} - ( \mathrm{e}^{t \mathbf{Z}_s} ) ^* \mathrm{e}^{t \mathbf{Z}_s} \bigr ) ^{ - 1}, \label{eq-all-s-hilbert-schmidt}\\*
    \tr_{\mathcal{H}} ( T_t^{ ( s ) } )
    & = \det ( \1_{2d} - \mathrm{e}^{t \mathbf{Z}} ) ^{ - 1}.\label{eq-all-s-trace}
\end{align}
If $ P_\rho Y := \langle \rho^{1/2}, Y \rangle_2 \rho^{1/2} $, then the operator norm on $ \mathcal{H} $ satisfies
\begin{equation}
    \label{eq-all-s-centered-bound}
    \norm{T_t^{ ( s ) } - P_\rho} = \norm{\mathrm{e}^{t \mathbf{Z}_s}} < 1, \qquad t > 0.
\end{equation}

By Theorem~\ref{theorem-all-s-representation}, the two norm formulas follow from \cite[Corollary~3.8]{ArakiSinhaSunder1995}. The trace formula in \cite[Remark~3.7(1)]{ArakiSinhaSunder1995} initially gives $ \det ( \1_{2d} - \mathrm{e}^{t \mathbf{Z}_s} ) ^{ - 1} $. Equation~\eqref{eq-definition-A-s} shows that $ \mathrm{e}^{t \mathbf{Z}_s} $ and $ \mathrm{e}^{t \mathbf{Z}} $ are similar, so
\begin{equation*}
    \det ( \1_{2d} - \mathrm{e}^{t \mathbf{Z}_s} ) = \det ( \1_{2d} - \mathrm{e}^{t \mathbf{Z}} ).
\end{equation*}
This gives the trace identity in terms of the original drift $ \mathbf{Z} $. Equation~\eqref{eq-all-s-centered-bound} is the tensor-norm calculation in the proof of Theorem~\ref{theorem-main}.

\label{corollary-spectrum}
Under the same assumptions, let $ \lambda_1, \ldots, \lambda_{2d} $ be the eigenvalues of $ \mathbf{Z} $, repeated according to algebraic multiplicity. Then, for every $ s \in [ 0, 1 ] $,
\begin{equation}
    \label{eq-all-s-generator-spectrum}
    \sigma ( L^{ ( s ) } ) =
    \left\{\sum_{j = 1}^{2d} \alpha_j \lambda_j : \alpha \in \mathbb{N}^{2d} \right\}.
\end{equation}
Every spectral value is an isolated eigenvalue of finite algebraic multiplicity. The algebraic multiplicity of $ \mu $ is
\begin{equation}
    \label{eq-algebraic-multiplicity}
    \#\left\{\alpha \in \mathbb{N}^{2d} : \sum_{j = 1}^{2d} \alpha_j \lambda_j = \mu \right\}.
\end{equation}
In particular, the spectrum and its algebraic multiplicities are independent of $ s $. The matrix $ \mathbf{Z} $ need not be diagonalizable.

Fix $ s \in [ 0, 1 ] $. By Corollary~\ref{corollary-generator-domain}, $ L^{ ( s ) } $ is unitarily equivalent to
\begin{equation*}
    U_s^* L^{ ( s ) } U_s = \bigoplus_{n = 0}^\infty \mathbf{Z}_{s, n}.
\end{equation*}
In particular, $ U_s $ maps every vector supported in the $ n $-particle subspace into $ \operatorname{Dom} L^{ ( s ) } $, with the generator action corresponding to the finite-dimensional matrix $ \mathbf{Z}_{s, n} $. We first determine the spectra of these matrices, then show that they account for the full spectrum and its algebraic multiplicities.

Since $ \mathbf{Z}_s $ is similar to $ \mathbf{Z} $, its eigenvalues are $ \lambda_1, \ldots, \lambda_{2d} $, with the same algebraic multiplicities. Schur triangularization gives an orthonormal basis $ u_1, \ldots, u_{2d} $ of $ \mathbb{C}^{2d} $ such that
\begin{equation*}
    \mathbf{Z}_s u_j = \lambda_j u_j + \sum_{i < j} c_{ij} u_i, \qquad 1 \leq j \leq 2d.
\end{equation*}
For $ \alpha \in \mathbb{N}^{2d} $ with $ \abs{\alpha} := \sum_{j = 1}^{2d} \alpha_j = n $, let $ u_\alpha $ be the normalized symmetrization of $ u_1^{ \otimes \alpha_1} \otimes \cdots \otimes u_{2d}^{ \otimes \alpha_{2d}} $. These vectors form an orthonormal basis of $ ( \mathbb{C}^{2d} ) ^{ \odot n} $. The operator $ \mathbf{Z}_{s, n} $ applies $ \mathbf{Z}_s $ to each tensor factor and adds the results. Its coefficient along $ u_\alpha $ is therefore $ \sum_{j = 1}^{2d} \alpha_j \lambda_j $. Every other term replaces one factor $ u_j $ by $ u_i $ with $ i < j $, and hence decreases $ \sum_{j = 1}^{2d} j \alpha_j $. Ordering the basis by this quantity makes $ \mathbf{Z}_{s, n} $ triangular. Consequently,
\begin{equation*}
    \det ( z \1 - \mathbf{Z}_{s, n} )
    = \prod_{\substack{\alpha \in \mathbb{N}^{2d} \\ \abs{\alpha} = n}}
    \left( z - \sum_{j = 1}^{2d} \alpha_j \lambda_j \right).
\end{equation*}
For $ n = 0 $, the only multiindex is $ \alpha = 0 $ and $ \mathbf{Z}_{s, 0} = 0 $, corresponding to the vacuum. Thus every value on the right-hand side of \eqref{eq-all-s-generator-spectrum} is an eigenvalue of some $ \mathbf{Z}_{s, n} $. Extending a corresponding eigenvector by zero in all other particle components and applying $ U_s $ gives an eigenvector of $ L^{ ( s ) } $.

To prove the reverse inclusion, we must exclude spectral values that do not come from a finite-dimensional restriction. Choose $ a > 0 $. Since $ L^{ ( s ) } $ generates a contraction semigroup, $ a $ belongs to its resolvent set, and Theorem~\ref{theorem-main} shows that $ R_a := ( a - L^{ ( s ) } ) ^{ - 1} $ is compact. The spectral correspondence for the resolvent gives
\begin{equation*}
    \mu \in \sigma ( L^{ ( s ) } )
    \quad \Longleftrightarrow \quad
    ( a - \mu ) ^{ - 1} \in \sigma ( R_a ) \setminus \{ 0 \}, \qquad \mu \neq a.
\end{equation*}
The compact-operator spectral theorem therefore implies that every spectral value of $ L^{ ( s ) } $ is an isolated eigenvalue of finite algebraic multiplicity. Indeed, if $ R_a Y = ( a - \mu ) ^{ - 1} Y $ with $ Y \neq 0 $, then $ Y = ( a - \mu ) R_a Y $ belongs to $ \operatorname{Dom} L^{ ( s ) } $, and applying $ a - L^{ ( s ) } $ gives $ L^{ ( s ) } Y = \mu Y $.

For such an eigenvector, write $ U_s^* Y = \bigoplus_{n = 0}^\infty f_n $. The direct-sum formula yields
\begin{equation*}
    ( \mathbf{Z}_{s, n} - \mu \1 ) f_n = 0, \qquad n \in \mathbb{N}.
\end{equation*}
At least one component $ f_n $ is nonzero, so $ \mu $ is an eigenvalue of that $ \mathbf{Z}_{s, n} $. The triangular calculation above proves \eqref{eq-all-s-generator-spectrum}.

It remains to compute algebraic multiplicities. Stability of $ \mathbf{Z} $ gives $ \delta := \min_{1 \leq j \leq 2d} ( - \Re \lambda_j ) > 0 $. Whenever $ \sum_{j = 1}^{2d} \alpha_j \lambda_j = \mu $, we have
\begin{equation*}
    \delta \abs{\alpha}
    \leq \sum_{j = 1}^{2d} \alpha_j ( - \Re \lambda_j ) = - \Re \mu.
\end{equation*}
Hence only finitely many particle subspaces can contribute to the eigenvalue $ \mu $. If $ Y $ is a generalized eigenvector, so that $ ( L^{ ( s ) } - \mu \1 ) ^k Y = 0 $ for some $ k \geq 1 $, projection of $ U_s^* Y $ onto each particle subspace gives
\begin{equation*}
    ( \mathbf{Z}_{s, n} - \mu \1 ) ^k f_n = 0.
\end{equation*}
Here the component identity follows by iterating the generator action on its domain. Whenever $ \mu \notin \sigma ( \mathbf{Z}_{s, n} ) $, the matrix $ \mathbf{Z}_{s, n} - \mu \1 $ is invertible, so $ f_n = 0 $. Conversely, generalized eigenvectors in the finitely many contributing particle subspaces can be combined into a finite-particle vector. It belongs to the domain of every power of the generator, and choosing $ k $ large enough to annihilate all its components gives a generalized eigenvector of $ L^{ ( s ) } $ after applying $ U_s $.

Thus the generalized eigenspace of $ L^{ ( s ) } $ at $ \mu $ is, under $ U_s $, the direct sum of the corresponding finite-dimensional generalized eigenspaces. Their dimensions add. The characteristic polynomial computed above shows that the contribution of the $ n $-particle subspace is
\begin{equation*}
    \# \left\{ \alpha \in \mathbb{N}^{2d} : \abs{\alpha} = n, \quad \sum_{j = 1}^{2d} \alpha_j \lambda_j = \mu \right\}.
\end{equation*}
Summing over $ n $ proves \eqref{eq-algebraic-multiplicity}. Both formulas depend only on the eigenvalues of $ \mathbf{Z} $, counted with algebraic multiplicity, and are therefore independent of $ s $. The argument uses triangularization and generalized eigenspaces, so it does not require diagonalizability of $ \mathbf{Z} $.

\label{proposition-interpolation}
Let $ \rho $ be a faithful density on a separable Hilbert space $ \mathsf{h} $, and let $ \Phi : \mathcal{B} ( \mathsf{h} ) \to \mathcal{B} ( \mathsf{h} ) $ be a normal unital completely positive map preserving $ \rho $. For $ s \in [ 0, 1 ] $, let $ B_s $ be its bounded implementation on $ \mathcal{H} = \mathcal{B}_2 ( \mathsf{h} ) $, determined by
\begin{equation*}
    B_s \bigl ( \rho^{s/2} X \rho^{ ( 1 - s ) /2} \bigr ) = \rho^{s/2} \Phi ( X ) \rho^{ ( 1 - s ) /2}, \qquad X \in \mathcal{B} ( \mathsf{h} ).
\end{equation*}
If $ B_0 $ is compact, then $ B_s $ is compact for every $ s \in [ 0, 1 ] $.

In the Hilbert--Schmidt realization of the GNS space, the modular operator associated with $ \rho $ acts as $ \Delta_\rho Y = \rho Y \rho^{ - 1} $ on its natural domain. Lemma~3.5 of \cite{OkayasuTomatsu2016} constructs the bounded implementations and gives complete positivity of $ B_0 $ with respect to the corresponding positive cone. The bounded extension of
\begin{equation*}
    \Delta_\rho^{s/2} B_0 \Delta_\rho^{ - s/2}
\end{equation*}
agrees with $ B_s $ on the dense span of embedded matrix units. Taking $ \alpha = 0 $ and $ \beta = s/2 $ in \cite[Lemma~3.15(i),(iii)]{OkayasuTomatsu2016} therefore gives compactness for the full interval $ 0 \leq s \leq 1 $. The nonzero condition in that lemma holds because $ B_0 \rho^{1/2} = \rho^{1/2} $.

\label{proposition-gap-compactness-diagram}
Let a finite-mode Gaussian QMS have a unique faithful normal invariant state. Then
\begin{equation}
    \label{eq-gap-compactness-diagram}
    \boxed{\begin{array}{ccc}
    \operatorname{gap} L^{ ( 0 ) } > 0 & \Longrightarrow & \operatorname{gap} L^{ ( 1/2 ) } > 0\\[5pt ]
    \Downarrow & & \Downarrow \\[5pt ]
    \begin{gathered}L^{ ( 0 ) } \text{ has}\\\text{compact resolvent}\end{gathered}
    & \Longleftrightarrow &
    \begin{gathered}L^{ ( 1/2 ) } \text{ has}\\\text{compact resolvent}.\end{gathered}
    \end{array}}
\end{equation}
Neither the upper horizontal implication nor either vertical implication can be reversed in general.

Wirth's comparison theorem \cite[Corollary~3.7]{Wirth2026}, together with \eqref{eq-gap-prefactor-one}, gives
\begin{equation*}
    \operatorname{gap} L^{ ( 1/2 ) } \geq \operatorname{gap} L^{ ( 0 ) }.
\end{equation*}
By Theorem~\ref{theorem-main}, uniqueness of the invariant state implies stability, so both statements in the lower row hold under the hypotheses of the proposition. We also give a direct proof of the vertical implications to explain how a positive spectral gap controls the resolvent.

Fix $ s \in [ 0, 1 ] $ and suppose that $ g := \operatorname{gap} L^{ ( s ) } > 0 $. The invariant state is Gaussian and $ \ker L^{ ( s ) } = \mathbb{C} \rho^{1/2} $. By Corollary~\ref{corollary-generator-domain}, every one-particle vector belongs to the domain of $ \lambda ( \mathbf{Z}_s ) $. Since $ U_s $ sends the vacuum to $ \rho^{1/2} $, the image under $ U_s $ of each one-particle vector is orthogonal to $ \ker L^{ ( s ) } $. Applying the gap inequality to $ U_s \xi $ gives
\begin{equation}
    \label{eq-gap-one-particle-coercivity}
    - \Re \langle \xi, \mathbf{Z}_s \xi \rangle \geq g \abs{\xi}^2, \qquad \xi \in \mathbb{C}^{2d}.
\end{equation}
Equivalently, $ - ( \mathbf{Z}_s + \mathbf{Z}_s^* ) /2 \geq g \1_{2d} $. The tensor-factor formula in \eqref{eq-second-quantized-generator} therefore yields
\begin{equation}
    \label{eq-gap-particle-coercivity}
    - \Re \langle f_n, \mathbf{Z}_{s, n} f_n \rangle \geq n g \norm{f_n}^2, \qquad f_n \in ( \mathbb{C}^{2d} ) ^{ \odot n}.
\end{equation}
For $ \eta > 0 $, Cauchy--Schwarz gives
\begin{equation*}
    ( \eta + n g ) \norm{f_n}^2 \leq \Re \langle f_n, ( \eta \1 - \mathbf{Z}_{s, n} ) f_n \rangle \leq \norm{f_n} \norm{( \eta \1 - \mathbf{Z}_{s, n} ) f_n}.
\end{equation*}
The estimate makes each finite-dimensional operator $ \eta \1 - \mathbf{Z}_{s, n} $ injective, hence invertible. Thus $ \norm{( \eta \1 - \mathbf{Z}_{s, n} ) ^{ - 1}} \leq ( \eta + n g ) ^{ - 1} $, with vacuum block $ \eta^{ - 1}\1 $. The direct-sum realization in Corollary~\ref{corollary-generator-domain} gives
\begin{equation*}
    U_s^* ( \eta \1 - L^{ ( s ) } ) ^{ - 1} U_s = \bigoplus_{n = 0}^\infty ( \eta \1 - \mathbf{Z}_{s, n} ) ^{ - 1}.
\end{equation*}
Using the finite-particle projections $ Q_{\leq r} $ from the proof of Theorem~\ref{theorem-main}, we obtain
\begin{equation}
    \label{eq-gap-resolvent-tail}
    \norm{U_s^* ( \eta \1 - L^{ ( s ) } ) ^{ - 1} U_s ( \1 - Q_{\leq r} )} \leq \frac{1}{\eta + ( r + 1 ) g} \longrightarrow 0, \qquad r \to \infty.
\end{equation}
Each particle subspace is finite dimensional because there are finitely many modes. Hence the resolvent is a norm limit of finite-rank operators and is compact. Taking $ s = 0 $ and $ s = 1/2 $ proves the two vertical implications.

The one-mode example in \cite[Sections~6 and~7.1]{fagnola2025spectral} has a unique faithful invariant state, a positive KMS spectral gap, and a zero GNS spectral gap; see also \cite[Remark~3.8]{Wirth2026}. Hence the upper implication cannot be reversed. Example~\ref{example-coupled-modes} has compact resolvent and zero coercive spectral gap for every embedding, which excludes both vertical converses.

\label{example-coupled-modes}
We use the two-mode example in \cite[Example~3.9]{li2026kms}. Choose $ v > u > 0 $ and put
\begin{equation*}
    \nu = \frac{v^2 + u^2}{v^2 - u^2}, \qquad
    E = \begin{bmatrix} 1 & 1 \\ 1 & 1 \end{bmatrix}, \qquad
    \Omega = \begin{bmatrix} \omega_1 & h \\ h & \omega_2 \end{bmatrix},
\end{equation*}
where $ \omega_1, \omega_2, h \in \mathbb{R} $ and $ \omega_1 \neq \omega_2 $. There is one Kraus operator, and the Hamiltonian contains a quadratic pairing term:
\begin{equation}
    \label{eq-example-H-L}
    \begin{aligned}
        L_1 & = v ( a_1 + a_2 ) + u ( a_1^\dagger + a_2^\dagger ),\\
        H & = \sum_{j, k = 1}^2 \Omega_{jk} a_j^\dagger a_k
        + \frac{\mathrm{i} u v}{2 \nu} \left( ( a_1^\dagger + a_2^\dagger ) ^2 - ( a_1 + a_2 ) ^2 \right).
    \end{aligned}
\end{equation}
The GKSL expression is
\begin{equation*}
    \mathcal{L} ( X ) = \mathrm{i} [ H, X ] + L_1^* X L_1
    - \frac{1}{2} L_1^* L_1 X - \frac{1}{2} X L_1^* L_1.
\end{equation*}
Set $ \alpha_\pm = ( v^2 - u^2 ) /2 \pm u v/\nu $. Both coefficients are positive, since $ v^2 + u^2 > 2 u v $. The drift and diffusion matrices are
\begin{equation}
    \label{eq-example-drift}
    \mathbf{Z} = \begin{bmatrix} - \alpha_+ E & - \Omega \\ \Omega & - \alpha_- E \end{bmatrix}, \qquad
    \mathbf{C} = \begin{bmatrix} ( v + u ) ^2 E & 0 \\ 0 & ( v - u ) ^2 E \end{bmatrix}.
\end{equation}
The symmetric part of the drift satisfies
\begin{equation}
    \label{eq-example-symmetric-part}
    \frac{\mathbf{Z} + \mathbf{Z}^*}{2}
    = - \begin{bmatrix} \alpha_+ E & 0 \\ 0 & \alpha_- E \end{bmatrix}, \qquad
    \ker ( \mathbf{Z} + \mathbf{Z}^* )
    = \operatorname{span} \{ ( 1, - 1, 0, 0 ) ^T, ( 0, 0, 1, - 1 ) ^T \}.
\end{equation}
Every eigenvalue of $ \mathbf{Z} $ has nonpositive real part. If $ \mathbf{Z} \xi = \lambda \xi $ with $ \Re \lambda = 0 $, then \eqref{eq-example-symmetric-part} forces $ \xi = ( x, - x, y, - y ) ^T $. Requiring $ \mathbf{Z} \xi $ to belong to the same kernel gives $ ( \omega_1 - \omega_2 ) x = ( \omega_1 - \omega_2 ) y = 0 $. Thus $ \xi = 0 $, a contradiction. Hence $ \mathbf{Z} $ is stable.

Put $ \beta = \log ( v^2/u^2 ) $. The centered Gaussian state with covariance $ \mathbf{S} = \nu \1_4 $ has density
\begin{equation}
    \label{eq-example-rho}
    \rho = \rho_{\beta} \otimes \rho_{\beta}.
\end{equation}
It is faithful because $ \beta > 0 $, and $ \mathbf{Z}^T \mathbf{S} + \mathbf{S} \mathbf{Z} = - \mathbf{C} $ proves invariance by \eqref{eq-gaussian-action}. Theorem~\ref{theorem-main} therefore gives uniqueness of the normal invariant state, immediate trace-class membership of every induced semigroup, and compact resolvent of every induced generator. In the KMS embedding, the common inverse temperature makes $ \mathbf{S}_{1/2} $ scalar, so $ \mathbf{Z}_{1/2} = \mathbf{Z} $. The nontrivial kernel in \eqref{eq-example-symmetric-part} shows that the KMS spectral gap vanishes, as established in \cite[Example~3.9]{li2026kms}.

In fact, the coercive spectral gap vanishes for every embedding. By Lemma~\ref{lemma-explicit-metric}, $ \mathbf{S}_s = c_{s, 1} \1_4 + \mathrm{i} d_{s, 1} \mathbf{J} $, with the coefficients evaluated at the common inverse temperature $ \beta $. The kernel in \eqref{eq-example-symmetric-part} is invariant under $ \mathbf{J} $, hence under $ \mathbf{S}_s^{ - 1/2} $. The skew-adjoint part of $ \mathbf{Z} $ commutes with $ \mathbf{J} $ and therefore with $ \mathbf{S}_s $. Consequently,
\begin{equation*}
    \mathbf{Z}_s \xi = \frac{\mathbf{Z} - \mathbf{Z}^*}{2} \xi, \qquad
    \xi \in \ker ( \mathbf{Z} + \mathbf{Z}^* ).
\end{equation*}
Regard any unit vector $ \xi $ in this kernel as a one-particle Fock vector. Then $ Y = U_s \xi $ belongs to $ \operatorname{Dom} L^{ ( s ) } $, is orthogonal to $ \rho^{1/2} $, and satisfies $ \Re \langle Y, L^{ ( s ) } Y \rangle_2 = 0 $. Contractivity gives $ \operatorname{gap} L^{ ( s ) } \geq 0 $, so $ \operatorname{gap} L^{ ( s ) } = 0 $ for every $ s \in [ 0, 1 ] $. Thus compactness does not imply the existence of a spectral gap, even in the KMS embedding.

\label{example-gap-infinite-kernel}
Let $ \mathcal{R}_t $ be the one-mode thermal Gaussian QMS with drift $ - \gamma\1_2 $, where $ \gamma > 0 $, and faithful thermal invariant state $ \rho_{\beta} $ from \eqref{eq-thermal-density}. One realization has zero Hamiltonian and Lindblad operators
\begin{equation*}
    L_{-} = \sqrt{\frac{2 \gamma}{1 - \mathrm{e}^{ - \beta}}}\,a,
    \qquad L_{+} = \sqrt{\frac{2 \gamma \mathrm{e}^{ - \beta}}{1 - \mathrm{e}^{ - \beta}}}\,a^\dagger.
\end{equation*}
On two modes, set $ \mathcal{T}_t = \mathrm{id} \otimes \mathcal{R}_t $ and choose the faithful invariant density $ \rho = \rho_{\beta} \otimes \rho_{\beta} $. Since the first factor has identity dynamics, the invariant state is not unique. Let $ G^{ ( s ) } $ denote the generator of the semigroup induced by $ \mathcal{R}_t $ with invariant density $ \rho_{\beta} $. Then
\begin{equation*}
    L^{ ( s ) } = I_{\mathcal{B}_2 ( \Gamma ( \mathbb{C} ) ) } \otimes G^{ ( s ) }.
\end{equation*}
By Theorem~\ref{theorem-all-s-representation},
$ G^{ ( s ) } $ is unitarily equivalent to $ - \gamma \lambda ( \1_2 ) $, whose restriction to the $ n $-particle subspace is multiplication by $ - \gamma n $. Hence
\begin{equation}
    \label{eq-infinite-kernel-gap}
    \ker L^{ ( s ) } = \mathcal{B}_2 ( \Gamma ( \mathbb{C} ) ) \otimes \mathbb{C} \rho_{\beta}^{1/2},
    \qquad \operatorname{gap} L^{ ( s ) } = \gamma.
\end{equation}
On the orthogonal complement of this kernel, only components with $ n \geq 1 $ in the thermal factor occur, giving the lower bound $ \gamma $. This bound is attained by the tensor product of a unit vector in the first factor and a unit eigenvector of $ G^{ ( s ) } $ with eigenvalue $ - \gamma $. The kernel is infinite dimensional, and the resolvent acts on it as $ ( \lambda - L^{ ( s ) } ) ^{ - 1} = \lambda^{ - 1} I $ for every $ \lambda > 0 $. Thus the resolvent is noncompact, although the coercive spectral gap defined by \eqref{eq-definition-coercive-gap} is positive. If coercivity were measured on $ \{\rho^{1/2}\}^{ \perp } $, the gap would instead be zero, since this space contains nonzero fixed vectors.
